    if (!target || !found.some((row) => row.id === sourceLabelId)) return null;

    const sourceIssueIds = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all()
      .map((row) => row.issueId);

    if (sourceIssueIds.length > 0) {
      tx.insert(issueLabels)
        .values(
          sourceIssueIds.map((issueId) => ({
            orgId,
            issueId,
            labelId: targetLabelId,
          })),
        )
        .onConflictDoNothing()
        .run();
    }
    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return {
      label: toLabel(target),
      issuesRelabelled: sourceIssueIds.length,
    };
  });
}

